def _check_sse_field_valid(v: str | None) -> str | None:
    if v is not None:
        if "\0" in v:
            raise ValueError("SSE field must not contain null characters.")
        if "\n" in v or "\r" in v:
            raise ValueError("SSE field must not contain multi-line content.")
    return v

